let data = '';
process.stdin.on('data', c => data += c);

function* nextLine() {
	let lines = data.trim().split(/\n/g);
	for(let l of lines){
		yield l.trim();
	}
}

let nl = nextLine();

nl.num = function() {
		return Number(this.next().value);
	};
nl.nums = function() {
		return this.next().value.split(/\s/g).map(Number);
	};
nl.line = function() {
		return this.next().value;
	}

const sol = () => {
	let [n, k] = nl.nums();
	let a = nl.nums();
	let r = Array(n);
	r.fill(0);
	for(let i of a){
		for(let j = i-1; j < n && r[j] === 0; j++){
			r[j] = i;
		}
	}
	console.log(r.join(' '));

};

process.stdin.on('end', sol);
